use searchkernel_vespa::{ConfigCompiler, Engine, Field, FieldType, Query, Schema};
use serde_json::Value;
use std::{fs,path::PathBuf};
fn q(v:&Value)->Query{match v["kind"].as_str().unwrap(){"term"=>Query::Term{field:v["field"].as_str().unwrap().into(),text:v["text"].as_str().unwrap().into()},"and"=>Query::And(v["children"].as_array().unwrap().iter().map(q).collect()),"or"=>Query::Or(v["children"].as_array().unwrap().iter().map(q).collect()),"equals"=>Query::Equals{field:v["field"].as_str().unwrap().into(),value:v["value"].as_i64().unwrap() as i32},_=>panic!("unsupported error fixture query")}}
fn classify(s:&str)->&'static str{let x=s.to_ascii_lowercase();if x.contains("unknown")&&x.contains("field"){"unknown_field"}else if x.contains("field")&&(x.contains("type")||x.contains("text")||x.contains("integer")){"wrong_field_type"}else if x.contains("unsupported")&&x.contains("yql"){"unsupported_yql"}else if x.contains("yql")||x.contains("parse"){"invalid_yql"}else{"invalid_query"}}
fn main(){let a:Vec<String>=std::env::args().collect(); let all:Value=serde_json::from_str(&fs::read_to_string(&a[2]).unwrap()).unwrap(); let id=&a[3]; let c=all["cases"].as_array().unwrap().iter().find(|x|x["id"]==*id).unwrap(); let mut s=Schema::new(c["schema"].as_str().unwrap()); for f in c["fields"].as_array().unwrap(){let k=match f["type"].as_str().unwrap(){"text"=>FieldType::Text,"integer"=>FieldType::Integer,_=>panic!()};let mut z=Field::new(f["name"].as_str().unwrap(),k);if f["index"].as_bool().unwrap(){z=z.indexed();}if f["attribute"].as_bool().unwrap(){z=z.attribute();}s=s.field(z);} let cfg=PathBuf::from(&a[4]);let data=PathBuf::from(&a[5]);ConfigCompiler::default().compile_to(&s,&cfg).unwrap();let e=Engine::open(&data,&cfg).unwrap(); let path=&a[1]; let r=if path=="typed"{e.search_query(&q(&c["typed"]),"default").map(|_|())}else{e.search_yql(c["yql"].as_str().unwrap(),"default").map(|_|())};match r{Ok(_)=>{eprintln!("unexpected success");std::process::exit(1)},Err(err)=>println!("{}",classify(&format!("{err:?}")))}}
